#include <libgen.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string>

#include <magic.h>

struct Environment {
  Environment(std::string data_dir) {
    magic = magic_open(MAGIC_NONE);
    std::string magic_path = data_dir + "/magic";
    if (magic_load(magic, magic_path.c_str())) {
      fprintf(stderr, "error loading magic file: %s\n", magic_error(magic));
      exit(1);
    }
  }

  magic_t magic;
};

static Environment* env;

extern "C" int LLVMFuzzerInitialize(int* argc, char*** argv) {
  char* exe_path = (*argv)[0];
  // dirname() can modify its argument.
  char* exe_path_copy = strdup(exe_path);
  char* dir = dirname(exe_path_copy);
  env = new Environment(dir);
  free(exe_path_copy);
  return 0;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
  if (size < 1)
    return 0;
  magic_buffer(env->magic, data, size);
  return 0;
}

magic_buffer(struct magic_set *ms, const void *buf, size_t nb)
{
        if (ms == NULL)
                return NULL;
        if (file_reset(ms) == -1)
                return NULL;
        /*
         * The main work is done here!
         * We have the file name and/or the data buffer to be identified.
         */
        if (file_buffer(ms, -1, NULL, buf, nb) == -1) {
                return NULL;
        }
        return file_getbuffer(ms);
}
#endif

public const char *
magic_error(struct magic_set *ms)
{
        if (ms == NULL)
                return "Magic database is not open";
        return (ms->event_flags & EVENT_HAD_ERR) ? ms->o.buf : NULL;
}

file_softmagic(struct magic_set *ms, const unsigned char *buf, size_t nbytes,
    uint16_t *indir_count, uint16_t *name_count, int mode, int text)
{
        struct mlist *ml;
        int rv, printed_something = 0, need_separator = 0;
        uint16_t nc, ic;

        if (name_count == NULL) {
                nc = 0;
                name_count = &nc;
        }
        if (indir_count == NULL) {
                ic = 0;
                indir_count = &ic;
        }

        for (ml = ms->mlist[0]->next; ml != ms->mlist[0]; ml = ml->next)
                if ((rv = match(ms, ml->magic, ml->nmagic, buf, nbytes, 0, mode,
                    text, 0, indir_count, name_count,
                    &printed_something, &need_separator, NULL)) != 0)
                        return rv;

        return 0;
}

#define FILE_FMTDEBUG
#ifdef FILE_FMTDEBUG
#define F(a, b, c) file_fmtcheck((a), (b), (c), __FILE__, __LINE__)

private const char * __attribute__((__format_arg__(3)))
file_fmtcheck(struct magic_set *ms, const struct magic *m, const char *def,
        const char *file, size_t line)
{
        const char *ptr = fmtcheck(m->desc, def);
        if (ptr == def)
                file_magerror(ms,
                    "%s, %" SIZE_T_FORMAT "u: format `%s' does not match"
                    " with `%s'", file, line, m->desc, def);
        return ptr;
}
#else
#define F(a, b, c) fmtcheck((b)->desc, (c))
#endif

/*
 * Go through the whole list, stopping if you find a match.  Process all
 * the continuations of that match before returning.
 *
 * We support multi-level continuations:
 *
 *      At any time when processing a successful top-level match, there is a
 *      current continuation level; it represents the level of the last
 *      successfully matched continuation.
 *
 *      Continuations above that level are skipped as, if we see one, it
 *      means that the continuation that controls them - i.e, the
 *      lower-level continuation preceding them - failed to match.
 *
 *      Continuations below that level are processed as, if we see one,
 *      it means we've finished processing or skipping higher-level
 *      continuations under the control of a successful or unsuccessful
 *      lower-level continuation, and are now seeing the next lower-level
 *      continuation and should process it.  The current continuation
 *      level reverts to the level of the one we're seeing.
 *
 *      Continuations at the current level are processed as, if we see
 *      one, there's no lower-level continuation that may have failed.
 *
 *      If a continuation matches, we bump the current continuation level
 *      so that higher-level continuations are processed.
